UPDATE `init_rtks_role` SET description='是网络安全领域的核心角色，通过模拟黑客攻击手段，对目标系统（如 Web 应用、网络基础设施、移动应用等）进行安全性测试，识别潜在漏洞并提供修复建议，以增强系统的抗攻击能力。' WHERE name='渗透测试工程师';
UPDATE `init_rtks_role` SET description='专注于设计与开发安全相关的软件、工具及系统，通过代码层面的安全能力构建，从源头预防漏洞，提升产品或系统的安全防护水平。' WHERE name='安全开发工程师';
UPDATE `init_rtks_role` SET description='负责收集、分析网络安全事件中的电子证据，还原攻击过程，为网络犯罪调查、法律诉讼或企业内部安全事件溯源提供技术支持。' WHERE name='安全取证工程师';
UPDATE `init_rtks_role` SET description='通过反汇编、反编译等技术，对软件、固件或恶意代码进行逆向分析，以识别漏洞、提取功能逻辑或分析恶意行为，为安全防御提供技术支撑。' WHERE name='逆向分析工程师';
UPDATE `init_rtks_role` SET description='负责企业安全基础设施的日常运维、安全事件响应及风险管控，通过监控、配置与优化安全设备，确保系统持续抵御网络攻击。' WHERE name='安全运维工程师';

